  def encode_enddate(value) when is_binary(value), do: value
  def encode_enddate(_), do: {:error, "Unexpected type when encoding Object.enddate"}

  def decode_phone(value) when is_binary(value), do: value
  def decode_phone(_), do: {:error, "Unexpected type when decoding Object.phone"}

  def encode_phone(value) when is_binary(value), do: value
  def encode_phone(_), do: {:error, "Unexpected type when encoding Object.phone"}

  def decode_startdate(value) when is_binary(value), do: value
  def decode_startdate(_), do: {:error, "Unexpected type when decoding Object.startdate"}

  def encode_startdate(value) when is_binary(value), do: value
  def encode_startdate(_), do: {:error, "Unexpected type when encoding Object.startdate"}

  def decode_state(value) when is_binary(value), do: value
  def decode_state(_), do: {:error, "Unexpected type when decoding Object.state"}

  def encode_state(value) when is_binary(value), do: value
  def encode_state(_), do: {:error, "Unexpected type when encoding Object.state"}

  def decode_website(value) when is_binary(value), do: value
  def decode_website(_), do: {:error, "Unexpected type when decoding Object.website"}

  def encode_website(value) when is_binary(value), do: value
  def encode_website(_), do: {:error, "Unexpected type when encoding Object.website"}

  def from_map(m) do
    %Object{
      caucus: m["caucus"] && Party.decode(m["caucus"]),
      congress_numbers: decode_congress_numbers(m["congress_numbers"]),
      current: decode_current(m["current"]),
      description: decode_description(m["description"]),
      district: decode_district(m["district"]),
      enddate: decode_enddate(m["enddate"]),
      extra: Extra.from_map(m["extra"]),
      leadership_title: Map.fetch!(m, "leadership_title"),
      party: Party.decode(m["party"]),
      person: Person.from_map(m["person"]),
      phone: decode_phone(m["phone"]),
      role_type: RoleType.decode(m["role_type"]),
      role_type_label: RoleTypeLabel.decode(m["role_type_label"]),
      senator_class: SenatorClass.decode(m["senator_class"]),
      senator_class_label: SenatorClassLabel.decode(m["senator_class_label"]),
      senator_rank: SenatorRank.decode(m["senator_rank"]),
      senator_rank_label: SenatorRankLabel.decode(m["senator_rank_label"]),
      startdate: decode_startdate(m["startdate"]),
      state: decode_state(m["state"]),
      title: Title.decode(m["title"]),
      title_long: RoleTypeLabel.decode(m["title_long"]),
      website: decode_website(m["website"]),
    }
  end

  def from_json(json) do
    json
          |> Jason.decode!()
          |> from_map()
  end

  def to_map(struct) do
    %{
      "caucus" => struct.caucus && Party.encode(struct.caucus),
      "congress_numbers" => struct.congress_numbers,
      "current" => struct.current,
      "description" => struct.description,
      "district" => struct.district,
      "enddate" => struct.enddate,
      "extra" => Extra.to_map(struct.extra),
      "leadership_title" => struct.leadership_title,
      "party" => Party.encode(struct.party),
      "person" => Person.to_map(struct.person),
      "phone" => struct.phone,
      "role_type" => RoleType.encode(struct.role_type),
      "role_type_label" => RoleTypeLabel.encode(struct.role_type_label),
      "senator_class" => SenatorClass.encode(struct.senator_class),
      "senator_class_label" => SenatorClassLabel.encode(struct.senator_class_label),
      "senator_rank" => SenatorRank.encode(struct.senator_rank),
      "senator_rank_label" => SenatorRankLabel.encode(struct.senator_rank_label),
      "startdate" => struct.startdate,
      "state" => struct.state,
      "title" => Title.encode(struct.title),
      "title_long" => RoleTypeLabel.encode(struct.title_long),
      "website" => struct.website,
    }
  end

  def to_json(struct) do
    struct
          |> to_map()
          |> Jason.encode!()
  end
end

defmodule TopLevel do
  @enforce_keys [:meta, :objects]
  defstruct [:meta, :objects]

  @type t :: %__MODULE__{
          meta: Meta.t(),
          objects: [Object.t()]
        }

  def decode_objects(value) when is_list(value), do: value
  def decode_objects(_), do: {:error, "Unexpected type when decoding TopLevel.objects"}

  def encode_objects(value) when is_list(value), do: value
  def encode_objects(_), do: {:error, "Unexpected type when encoding TopLevel.objects"}

  def from_map(m) do
    %TopLevel{
      meta: Meta.from_map(m["meta"]),
      objects: Enum.map(m["objects"], &Object.from_map/1),
    }
  end

  def from_json(json) do
    json
          |> Jason.decode!()
          |> from_map()
  end

  def to_map(struct) do
    %{
      "meta" => Meta.to_map(struct.meta),
      "objects" => struct.objects && Enum.map(struct.objects, &Object.to_map/1),
    }
  end

  def to_json(struct) do
    struct
          |> to_map()
          |> Jason.encode!()
  end
end
